insert into public.training_sources(source_key,authority,title,source_type,canonical_url,publication_date,checked_on,license_kind,reuse_policy,normative_status,topics,notes,metadata)
values
('inail-agricoltura-sicurezza','INAIL','Agricoltura - ricerca e strumenti per la sicurezza di macchine, trattori e attività agro-forestali','institutional_technical','https://www.inail.it/portale/ricerca-e-tecnologia/it/ambiti-di-ricerca/area-sicurezza-sul-lavoro/agricoltura.html',null,date '2026-10-16','institutional_terms','facts_and_original_didactic_rewrite','supporting',array['agricoltura','silvicoltura','trattori','macchine agricole','prodotti fitosanitari'],'Fonte tecnica INAIL per rischi e prevenzione in agricoltura; uso per fatti e criteri con riscrittura didattica originale.',jsonb_build_object('priority','high_evidence')),
('inail-agricoltura-infortuni-2024','INAIL','Infortuni mortali nelle lavorazioni agricole','incident_evidence','https://www.inail.it/portale/it/inail-comunica/news/notizia.2024.11.infortuni-mortali-nelle-lavorazioni-agricole.html',date '2024-11-22',date '2026-10-16','institutional_terms','facts_and_original_didactic_rewrite','supporting',array['agricoltura','infortuni','trattori','ribaltamento','silvicoltura'],'Evidence INAIL su dinamiche infortunistiche agricole e ruolo di trattori/ROPS/FOPS; riscrittura originale.',jsonb_build_object('priority','high_evidence')),
('inail-pesca-pmp','INAIL','Pescare in sicurezza: piano mirato di prevenzione nel settore pesca','institutional_technical','https://www.inail.it/content/dam/inail-hub-site/documenti/2024/10/Report_Bari2.pdf',null,date '2026-10-16','institutional_terms','facts_and_original_didactic_rewrite','supporting',array['pesca','imbarcazioni','fatica','ambienti di lavoro','DPI','attrezzature'],'Fonte INAIL per rischi caratteristici della pesca, organizzazione del lavoro e prevenzione; contenuti SafetyTraining originali.',jsonb_build_object('priority','high_evidence')),
('normattiva-dlgs271-1999','Normattiva','D.Lgs. 27 luglio 1999, n. 271 - sicurezza e salute dei lavoratori marittimi a bordo','normative_source','https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:1999-07-27;271=',date '1999-07-27',date '2026-10-16','public_law','reference_only','normative',array['pesca','lavoratori marittimi','armatore','navi da pesca','piano sicurezza'],'Fonte normativa specifica per lavoro marittimo e pesca.',jsonb_build_object('priority','primary_normative')),
('inail-agenti-chimici','INAIL','Agenti chimici - valutazione e gestione del rischio','institutional_technical','https://www.inail.it/portale/prevenzione-e-sicurezza/it/come-fare-per/conoscere-il-rischio/agenti-chimici.html',null,date '2026-10-16','institutional_terms','facts_and_original_didactic_rewrite','supporting',array['agenti chimici','sostanze pericolose','CLP','REACH','valutazione rischio'],'Fonte tecnica INAIL per valutazione e gestione del rischio chimico; riscrittura originale.',jsonb_build_object('priority','high_evidence')),
('inail-atex','INAIL','Atmosfere esplosive - prevenzione e protezione','institutional_technical','https://www.inail.it/portale/prevenzione-e-sicurezza/it/come-fare-per/conoscere-il-rischio/atmosfere-esplosive.html',null,date '2026-10-16','institutional_terms','facts_and_original_didactic_rewrite','supporting',array['ATEX','atmosfere esplosive','incendio','esplosione','chimico'],'Fonte tecnica INAIL per rischio ATEX e criteri di prevenzione/protezione.',jsonb_build_object('priority','high_evidence')),
('normattiva-dlgs105-2015','Normattiva','D.Lgs. 26 giugno 2015, n. 105 - controllo del pericolo di incidenti rilevanti connessi con sostanze pericolose','normative_source','https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:2015-06-26;105!vig=',date '2015-06-26',date '2026-10-16','public_law','reference_only','normative',array['incidenti rilevanti','Seveso','sostanze pericolose','chimico','petrolchimico'],'Fonte normativa per stabilimenti soggetti alla disciplina degli incidenti rilevanti.',jsonb_build_object('priority','primary_normative'))
on conflict (source_key) do update set authority=excluded.authority,title=excluded.title,source_type=excluded.source_type,canonical_url=excluded.canonical_url,publication_date=excluded.publication_date,checked_on=excluded.checked_on,license_kind=excluded.license_kind,reuse_policy=excluded.reuse_policy,normative_status=excluded.normative_status,topics=excluded.topics,notes=excluded.notes,metadata=excluded.metadata,updated_at=now();

with target as (
  select lu.id learning_unit_id, lu.stable_key, lu.title, lu.default_minutes,
         (select max(v.version_number)+1 from public.learning_unit_versions v where v.learning_unit_id=lu.id) target_version,
         (select v.content from public.learning_unit_versions v where v.learning_unit_id=lu.id order by v.version_number desc limit 1) old_content,
         case
           when lu.stable_key like 'dl-rspp:%' then 'common'
           when lu.stable_key like 'agg-dl-rspp:%' then 'update'
           when lu.stable_key like 'dl-rspp-sector:agricoltura_zootecnia:%' then 'agri'
           when lu.stable_key like 'dl-rspp-sector:pesca:%' then 'pesca'
           when lu.stable_key like 'dl-rspp-sector:chimico_petrolchimico:%' then 'chimico'
         end family,
         regexp_replace(lu.title,'^[^·]+·[[:space:]]*','') topic
  from public.learning_units lu
  where lu.stable_key like 'dl-rspp:%'
     or lu.stable_key like 'agg-dl-rspp:%'
     or lu.stable_key like 'dl-rspp-sector:agricoltura_zootecnia:%'
     or lu.stable_key like 'dl-rspp-sector:pesca:%'
     or lu.stable_key like 'dl-rspp-sector:chimico_petrolchimico:%'
), ctx as (
  select t.*,
    case family when 'agri' then 'agricoltura, silvicoltura e zootecnia' when 'pesca' then 'pesca e lavoro a bordo' when 'chimico' then 'chimico-petrolchimico' else null end sector,
    case
      when stable_key='dl-rspp:processo-valutazione' then 'Il processo parte dal lavoro reale: attività, pericoli, esposti, stima, priorità, misure, rischio residuo e riesame devono formare una catena decisionale tracciabile.'
      when stable_key='dl-rspp:strumenti-metodologie' then 'Scegliere metodo e livello di approfondimento in funzione del rischio: osservazione, dati, misure, checklist e competenze specialistiche vanno combinati senza trasformare la matrice in un fine.'
      when stable_key='dl-rspp:dvr-struttura-contenuti' then 'Il DVR deve descrivere rischi e decisioni: misure attuate, programma, responsabilità, priorità, criteri e condizioni che impongono il riesame.'
      when stable_key='dl-rspp:nearmiss-documentazione' then 'Near miss e anomalie sono dati di prevenzione: vanno raccolti, analizzati per cause tecniche/organizzative/procedurali e trasformati in azioni verificabili.'
      when stable_key='dl-rspp:rischi-operativi-ergonomici' then 'Luoghi, attrezzature, movimentazione e VDT richiedono osservazione delle condizioni reali, delle interazioni uomo-macchina e dell’organizzazione del compito.'
      when stable_key='dl-rspp:agenti-rischio' then 'Agenti fisici, chimici e biologici e atmosfere esplosive richiedono criteri specifici, dati di esposizione e misure coerenti con la gerarchia della prevenzione.'
      when stable_key='dl-rspp:psicosociale-misure-dpi' then 'La valutazione deve includere fattori psicosociali e differenze individuali e tradursi prima in misure tecniche/organizzative, poi nei DPI quando necessari.'
      when stable_key='dl-rspp:esercitazione-dvr-ateco' then 'L’esercitazione dimostra competenza solo se il DVR nasce da un caso ATECO concreto e collega attività, esposizioni, criteri, misure, priorità e programma.'
      when stable_key='agg-dl-rspp:novita-cambiamenti' then 'L’aggiornamento parte dai cambiamenti normativi, tecnici e organizzativi realmente intervenuti e dal loro impatto sul sistema di valutazione e prevenzione.'
      when stable_key='agg-dl-rspp:riesame-dvr' then 'Il DVR va riesaminato alla luce di cambiamenti, eventi, nuove conoscenze, misure non efficaci e rischi emergenti, evitando aggiornamenti puramente documentali.'
      when stable_key='agg-dl-rspp:eventi-indicatori' then 'Infortuni, near miss, audit e indicatori devono evidenziare trend e cause ricorrenti e guidare priorità prima che si produca un danno.'
      when stable_key='agg-dl-rspp:metodi-approfondimenti' then 'Il DL-RSPP deve riconoscere quando la valutazione interna non basta e servono misurazioni, metodi specialistici o competenze esterne.'
      when stable_key='agg-dl-rspp:efficacia-misure' then 'Una misura è chiusa solo quando attuata e verificata: manutenzione, protezioni, DPI e procedure richiedono evidenze di efficacia e gestione delle deviazioni.'
      when stable_key='agg-dl-rspp:ruoli-competenze' then 'Ruoli e competenze devono seguire l’organizzazione reale: cambi di persone, mansioni, turni e processi richiedono riallineamento di formazione, coordinamento e vigilanza.'
      when stable_key='agg-dl-rspp:settori-applicabili' then 'Se permangono le condizioni dei moduli specialistici frequentati, l’aggiornamento deve riguardare anche le relative tematiche; la scelta va motivata dal settore e dalle attività effettive.'
      when stable_key='agg-dl-rspp:riesame-finale' then 'Il riesame finale traduce criticità e nuove conoscenze in decisioni: misura, owner, risorsa, scadenza, indicatore e verifica.'
      when family='agri' and stable_key like '%:ud1' then 'Leggere gli infortuni del comparto per riconoscere dinamiche ricorrenti, con particolare attenzione a trattori, macchine, attività forestali e organizzazione del lavoro.'
      when family='agri' and stable_key like '%:ud2' then 'Serre, campi, boschi, stalle e aree esterne cambiano continuamente esposizioni, viabilità, microclima, accessi, isolamento e modalità di soccorso.'
      when family='agri' and stable_key like '%:ud3' then 'Strutture rurali e impianti devono essere mantenuti e modificati con criteri di sicurezza, tracciando conformità, manutenzione e cambiamenti d’uso.'
      when family='agri' and stable_key like '%:ud4' then 'Ribaltamento, schiacciamento, investimento e organi in movimento richiedono scelta corretta della macchina, protezioni, manutenzione, procedure e competenze dell’operatore.'
      when family='agri' and stable_key like '%:ud5' then 'Prodotti fitosanitari, detergenti, carburanti e altre sostanze vanno valutati considerando pericolo, esposizione, stoccaggio, miscelazione, rientro e gestione dei residui.'
      when family='agri' and stable_key like '%:ud6' then 'Contatto con animali, materiale organico, acque e suolo può generare esposizioni biologiche: servono igiene, procedure, vaccinazioni/sorveglianza quando previste e gestione degli eventi.'
      when family='agri' and stable_key like '%:ud7' then 'Rumore, vibrazioni, microclima, UV e altri agenti fisici vanno collegati a durata, intensità e reale modalità di lavoro.'
      when family='agri' and stable_key like '%:ud8' then 'Silos, vasche, cisterne, fosse e altri spazi possono diventare ambienti confinati o sospetti di inquinamento: accesso solo dopo qualificazione, valutazione e procedura specifica.'
      when family='agri' and stable_key like '%:ud9' then 'Materiali combustibili, depositi, carburanti, impianti e lavorazioni a caldo richiedono prevenzione incendio, controllo delle fonti di innesco e organizzazione dell’emergenza.'
      when family='agri' and stable_key like '%:ud10' then 'Lavori su tetti, alberi, scale, piattaforme e dislivelli richiedono priorità alla protezione collettiva, accessi sicuri e pianificazione del recupero.'
      when family='agri' and stable_key like '%:ud11' then 'Carichi variabili, posture, traino/spinta e movimentazione meccanica vanno analizzati insieme a ritmi, distanze, ausili e condizioni del terreno.'
      when family='pesca' and stable_key like '%:ud1' then 'Gli eventi del comparto vanno letti insieme a condizioni meteo-marine, spazi ristretti, fatica, attrezzature, cadute e lavoro fuori bordo.'
      when family='pesca' and stable_key like '%:ud2' then 'Il quadro specifico del lavoro marittimo integra la disciplina generale: armatore, comandante, piano di sicurezza e caratteristiche tecnico-operative dell’unità devono essere letti insieme.'
      when family='pesca' and stable_key like '%:ud3' then 'Ponte, sala macchine, locali di lavoro e alloggi sono ambienti mobili e confinati, influenzati da mare, spazi, turni, fatica e interferenze operative.'
      when family='pesca' and stable_key like '%:ud4' then 'Strutture e impianti di bordo devono mantenere condizioni di sicurezza anche con usura, corrosione, modifiche, manutenzioni e condizioni marine gravose.'
      when family='pesca' and stable_key like '%:ud5' then 'Argani, verricelli, cavi, reti e altre attrezzature generano trascinamento, schiacciamento, rottura e investimento: servono zone sicure, comunicazioni e arresto controllato.'
      when family='pesca' and stable_key like '%:ud6' then 'Carburanti, oli, detergenti e altre sostanze richiedono identificazione, stoccaggio, ventilazione, gestione delle perdite e compatibilità con gli spazi di bordo.'
      when family='pesca' and stable_key like '%:ud7' then 'Pesce, materiale organico, acque e contaminanti possono generare esposizioni biologiche e cutanee da governare con igiene e procedure.'
      when family='pesca' and stable_key like '%:ud8' then 'Rumore, vibrazioni, freddo, caldo e radiazione solare si combinano con turni e fatica e richiedono valutazione dell’esposizione reale.'
      when family='pesca' and stable_key like '%:ud9' then 'Stive, casse, serbatoi e locali tecnici possono presentare carenza di ossigeno o contaminanti: l’ingresso non è un’attività ordinaria e richiede procedura specifica.'
      when family='pesca' and stable_key like '%:ud10' then 'Incendio a bordo richiede prevenzione, compartimentazione, disponibilità dei presidi, addestramento e decisioni compatibili con la limitata possibilità di evacuazione.'
      when family='pesca' and stable_key like '%:ud11' then 'Scivolamenti, cadute in mare e lavori fuori bordo richiedono superfici sicure, protezioni, DPI adeguati, comunicazioni e recupero uomo a mare.'
      when family='pesca' and stable_key like '%:ud12' then 'Movimentazione di cassette, reti, attrezzi e carichi sospesi richiede valutazione ergonomica e coordinamento con gli ausili meccanici.'
      when family='pesca' and stable_key like '%:ud13' then 'Attività subacquee o iperbariche richiedono riconoscimento dei limiti di competenza, pianificazione specialistica, idoneità e procedure dedicate; non vanno improvvisate nel normale assetto di bordo.'
      when family='chimico' and stable_key like '%:ud1' then 'L’analisi degli eventi del comparto deve distinguere esposizioni croniche, perdite di contenimento, manutenzioni, avviamenti/arresti e deviazioni di processo.'
      when family='chimico' and stable_key like '%:ud2' then 'Processo, layout, turni, controllo remoto, stoccaggi e interfacce tra reparti determinano l’esposizione e la capacità di intercettare le deviazioni.'
      when family='chimico' and stable_key like '%:ud3' then 'Integrità di strutture e impianti dipende da progettazione, ispezione, manutenzione, gestione delle modifiche e documentazione tecnica aggiornata.'
      when family='chimico' and stable_key like '%:ud4' then 'Negli stabilimenti soggetti alla disciplina Seveso il pericolo di incidente rilevante richiede una visione di sistema su sostanze, scenari, barriere e conseguenze, distinta ma coordinata con la SSL.'
      when family='chimico' and stable_key like '%:ud5' then 'La presenza di lavorazioni insalubri richiede lettura coordinata di autorizzazioni, igiene industriale, emissioni e protezione dei lavoratori, senza confondere i diversi regimi normativi.'
      when family='chimico' and stable_key like '%:ud6' then 'Pressioni, temperature, energia, parti in movimento e sostanze di processo richiedono integrità delle attrezzature, interblocchi, isolamento e procedure operative affidabili.'
      when family='chimico' and stable_key like '%:ud7' then 'Le manutenzioni e i fornitori concentrano rischi durante aperture, bonifiche, isolamenti e lavori non routinari: qualificazione, permessi e coordinamento devono precedere l’avvio.'
      when family='chimico' and stable_key like '%:ud8' then 'Inventario, SDS, classificazione, incompatibilità, esposizione e quantità presenti guidano la valutazione del rischio chimico e la gerarchia delle misure.'
      when family='chimico' and stable_key like '%:ud9' then 'Rumore, vibrazioni, calore, radiazioni e altri agenti fisici vanno valutati considerando sorgenti, tempi, schermature e manutenzione.'
      when family='chimico' and stable_key like '%:ud10' then 'Incendio ed esplosione richiedono controllo di combustibili e sorgenti di innesco, classificazione ATEX quando applicabile, barriere, allarmi e risposta all’emergenza.'
      when family='chimico' and stable_key like '%:ud11' then 'Reattori, serbatoi, colonne, pozzetti e locali tecnici possono diventare ambienti confinati: isolamento, bonifica, verifica atmosfera, presidio e soccorso sono condizioni di ingresso.'
      when family='chimico' and stable_key like '%:ud12' then 'La protezione collettiva precede quella individuale; selezione dei DPI deve derivare da scenario, sostanza, compatibilità, durata, addestramento e manutenzione.'
      when family='chimico' and stable_key like '%:ud13' then 'Rifiuti e residui di processo mantengono proprietà pericolose: classificazione, segregazione, stoccaggio e trasferimento devono evitare esposizioni e incompatibilità.'
    end focus
  from target t
), tailored as (
  select c.*,
    case when family in ('common','update') then coalesce(old_content->>'summary',focus) else 'Nel settore '||sector||', il tema “'||topic||'” deve essere governato a partire dalle attività reali e dalle condizioni operative. '||focus end new_summary,
    case when family in ('common','update') then coalesce(old_content->>'detail',focus)||' Il docente deve far esplicitare dati disponibili, decisioni, misure, responsabilità, condizioni di STOP e modalità di verifica dell’efficacia.' else focus||' La trattazione collega pericoli, esposizioni, misure tecniche/organizzative/procedurali, responsabilità, documentazione ed evidenze di efficacia, distinguendo ciò che il DL-RSPP può governare direttamente da ciò che richiede competenze specialistiche.' end new_detail,
    case
      when family='agri' then case when stable_key like '%:ud4' then 'Un trattore deve operare su terreno inclinato con attrezzatura portata e passaggi stretti: individuare condizioni di STOP, protezioni e decisioni organizzative prima dell’avvio.' when stable_key like '%:ud8' then 'Una vasca interrata deve essere ispezionata dopo un fermo prolungato: decidere se l’accesso è necessario e quali prerequisiti impediscono un ingresso improvvisato.' else 'Una piccola azienda agro-forestale introduce una nuova attività relativa a '||lower(topic)||': individuare pericoli, esposti, misura immediata, misura strutturale e verifica.' end
      when family='pesca' then case when stable_key like '%:ud11' then 'Durante recupero reti con ponte bagnato e moto ondoso un addetto deve operare vicino al bordo: definire protezioni, comunicazioni, STOP e recupero uomo a mare.' when stable_key like '%:ud13' then 'Si propone un intervento subacqueo non routinario da eseguire con personale di bordo: riconoscere i limiti e definire il percorso specialistico prima di autorizzare l’attività.' else 'Durante una battuta di pesca cambia una condizione relativa a '||lower(topic)||': distinguere misura immediata, decisione del comandante/armatore e intervento da pianificare a terra.' end
      when family='chimico' then case when stable_key like '%:ud4' then 'Una modifica di processo aumenta l’inventario di una sostanza pericolosa: verificare se cambiano scenari, barriere e obblighi collegati al rischio di incidente rilevante.' when stable_key like '%:ud7' then 'Un fornitore deve aprire una linea per manutenzione: costruire il gate di lavoro con isolamento, bonifica, permesso, coordinamento e verifica finale.' when stable_key like '%:ud10' then 'Una perdita di solvente genera vapori in area con possibili sorgenti di innesco: definire azioni immediate, delimitazione, controllo delle sorgenti e criteri di rientro.' else 'Un impianto chimico modifica una condizione relativa a '||lower(topic)||': individuare deviazione, barriera preventiva, barriera protettiva, owner e verifica.' end
      when family='common' then 'Applicare il tema a un caso ATECO coerente con i partecipanti e produrre una decisione documentata: fatti, rischio, misura, owner, scadenza e criterio di efficacia.'
      else 'Partendo da un cambiamento realmente avvenuto nel quinquennio, decidere cosa riesaminare, quale evidenza richiedere e quale azione chiudere con responsabile e scadenza.'
    end case_text,
    case
      when family='agri' then jsonb_build_array('mlps-asr-2025','normattiva-dlgs81-vigente','inail-agricoltura-sicurezza') || case when stable_key like '%:ud1' or stable_key like '%:ud4' then jsonb_build_array('inail-agricoltura-infortuni-2024') else '[]'::jsonb end || case when stable_key like '%:ud8' then jsonb_build_array('normattiva-dpr177-2011','inail-informo-confinati-11') else '[]'::jsonb end
      when family='pesca' then jsonb_build_array('mlps-asr-2025','normattiva-dlgs81-vigente','normattiva-dlgs271-1999','inail-pesca-pmp') || case when stable_key like '%:ud9' then jsonb_build_array('normattiva-dpr177-2011','inail-informo-confinati-11') else '[]'::jsonb end
      when family='chimico' then jsonb_build_array('mlps-asr-2025','normattiva-dlgs81-vigente','inail-agenti-chimici') || case when stable_key like '%:ud4' then jsonb_build_array('normattiva-dlgs105-2015') else '[]'::jsonb end || case when stable_key like '%:ud10' then jsonb_build_array('inail-atex') else '[]'::jsonb end || case when stable_key like '%:ud11' then jsonb_build_array('normattiva-dpr177-2011','inail-informo-confinati-11') else '[]'::jsonb end
      when stable_key in ('dl-rspp:nearmiss-documentazione','agg-dl-rspp:eventi-indicatori') then jsonb_build_array('mlps-asr-2025','normattiva-dlgs81-vigente','piemonte-indicazioni-formazione-2025','inail-condivido-near-miss')
      when stable_key in ('dl-rspp:psicosociale-misure-dpi','agg-dl-rspp:riesame-dvr') then jsonb_build_array('mlps-asr-2025','normattiva-dlgs81-vigente','piemonte-indicazioni-formazione-2025','inail-stress-methodology-2025')
      else jsonb_build_array('mlps-asr-2025','normattiva-dlgs81-vigente','piemonte-indicazioni-formazione-2025')
    end source_keys
  from ctx c
), enriched as (
  select learning_unit_id,stable_key,target_version,source_keys,
    old_content || jsonb_build_object(
      'summary',new_summary,'detail',new_detail,'focus',focus,'case',case_text,
      'question',coalesce(old_content->>'question','Quale decisione operativa rende controllabile questo rischio o requisito nel contesto reale?'),
      'question_explanation','La risposta attesa deve collegare il fatto osservabile al rischio, scegliere una misura coerente con la gerarchia della prevenzione, indicare chi deve agire, quando fermarsi o fare escalation e quale evidenza dimostrerà l’efficacia. Nel caso specifico il punto chiave è: '||focus,
      'common_errors',jsonb_build_array('Usare una valutazione standard senza verificare il lavoro reale.','Confondere presenza di un documento con controllo effettivo del rischio.','Assegnare una misura senza owner, risorse, scadenza o verifica.','Continuare l’attività quando mancano condizioni essenziali di sicurezza o competenze necessarie.'),
      'teacher_activity',jsonb_build_object('prompt',case_text,'method','Far descrivere prima i fatti senza soluzioni; poi costruire pericoli/esposti, misure, responsabilità, STOP ed evidenza di efficacia.','debrief','Confrontare la decisione del gruppo con obblighi, gerarchia delle misure, competenze disponibili e condizioni operative reali.'),
      'operational',coalesce(old_content->'operational','{}'::jsonb) || jsonb_build_object('before',jsonb_build_array('Definisci attività, luogo, persone esposte e condizioni anomale.','Raccogli documenti, dati, misurazioni, eventi e manutenzioni pertinenti.'),'during',jsonb_build_array('Individua pericoli e scenari credibili.','Valuta rischio e priorità con criteri espliciti.','Scegli misure tecniche, organizzative e procedurali prima dei soli DPI.','Assegna responsabilità, risorse e tempi.'),'after',jsonb_build_array('Verifica attuazione ed efficacia.','Registra evidenze, rischio residuo e azioni aperte.','Riesamina al cambiamento o a segnali di inefficacia.'),'if_problem',jsonb_build_array('Metti in sicurezza persone e area.','Sospendi o limita l’attività se manca una barriera essenziale.','Coinvolgi la competenza specialistica necessaria prima di riprendere.'),'who_to_involve',case when family='pesca' then jsonb_build_array('Datore di lavoro/armatore','Comandante','Lavoratori e preposti di bordo','RLS quando pertinente','Tecnici e specialisti secondo il rischio') when family='chimico' then jsonb_build_array('Datore di lavoro/DL-RSPP','Dirigenti e preposti','Manutenzione/process engineering','RLS e medico competente quando pertinenti','Fornitori e specialisti autorizzati') else jsonb_build_array('Datore di lavoro/DL-RSPP','Dirigenti e preposti','Lavoratori/RLS','Medico competente quando pertinente','Tecnici o manutentori competenti') end,'stop_conditions',jsonb_build_array('Rischio grave non controllato o barriera essenziale assente.','Informazioni insufficienti per autorizzare un’attività non routinaria.','Attrezzatura, impianto o ambiente in condizioni non verificate.','Competenze o qualificazioni necessarie non disponibili.'),'adaptation',case when family in ('agri','pesca','chimico') then 'Adattare il materiale alle attività effettive del settore, alle attrezzature, agli ambienti e al DVR/piano di sicurezza dell’organizzazione.' else 'Adattare esempi e decisioni al settore ATECO e al DVR reale dei partecipanti.' end),
      'graphic_cards',jsonb_build_array(jsonb_build_object('title','Focus tecnico','body',focus),jsonb_build_object('title','Caso decisionale','body',case_text),jsonb_build_object('title','STOP','body','Non procedere quando manca una barriera essenziale, una verifica necessaria o la competenza richiesta.')),
      'formative_check',jsonb_build_object('question',coalesce(old_content->>'question','Quale decisione operativa rende controllabile questo rischio o requisito nel contesto reale?'),'explanation','La spiegazione deve ricondurre la risposta a scenario, gerarchia delle misure, responsabilità, condizioni di STOP e verifica dell’efficacia.','formative_only',true,'test_builder_excluded',true),
      'didactic_version','dl-rspp-authored-v3','source_keys',source_keys,
      'source_audit',jsonb_build_object('status','reviewed','checked_on','2026-10-16','reuse_policy','reference_and_original_rewrite','normative_validation','D.Lgs. 81/2008 vigente + Accordo Stato-Regioni 17/04/2025 Rep. 59/CSR; fonti specialistiche applicate per settore'),
      'source_integration_note','Le fonti sono usate per validazione normativa, dati e metodo. Testi, casi, sequenze operative e spiegazioni SafetyTraining sono originali. Le domande sono formative e separate dal Test Builder.',
      'quality',coalesce(old_content->'quality','{}'::jsonb) || jsonb_build_object('teacher_ready',true,'learner_ready',true,'decision_based',true,'transfer_to_work',true,'authored_presentation',true,'question_has_explanation',true,'formative_checks_only',true,'final_assessment',false,'test_builder_excluded',true),
      'final_assessment',false
    ) new_content
  from tailored
), final_content as (
  select e.*, e.new_content || jsonb_build_object('evidence_sources',coalesce((select jsonb_agg(jsonb_build_object('source_key',ts.source_key,'authority',ts.authority,'title',ts.title,'url',ts.canonical_url,'checked_on','2026-10-16','use','authored_evidence') order by ts.source_key) from jsonb_array_elements_text(e.source_keys) sk(source_key) join public.training_sources ts on ts.source_key=sk.source_key),'[]'::jsonb)) content_final from enriched e
)
insert into public.learning_unit_versions(learning_unit_id,version_number,status,content,content_hash,published_at)
select learning_unit_id,target_version,'draft',content_final,md5(content_final::text),null from final_content
on conflict (learning_unit_id,version_number) do update set status='draft',content=excluded.content,content_hash=excluded.content_hash,published_at=null;

with authored as (
 select lu.id learning_unit_id,luv.content->'source_keys' source_keys from public.learning_units lu join public.learning_unit_versions luv on luv.learning_unit_id=lu.id where luv.content->>'didactic_version'='dl-rspp-authored-v3' and luv.status='draft'
)
insert into public.learning_unit_sources(learning_unit_id,source_key,purpose,relevance_note,verified_on,metadata)
select a.learning_unit_id,sk.source_key,'authored_evidence_v3','Fonte usata per validazione normativa, approfondimento tecnico o metodo nella versione authored-v3 DL-RSPP.',date '2026-10-16',jsonb_build_object('didactic_version','dl-rspp-authored-v3','reuse_policy','reference_and_original_rewrite') from authored a cross join lateral jsonb_array_elements_text(a.source_keys) sk(source_key) join public.training_sources ts on ts.source_key=sk.source_key
on conflict (learning_unit_id,source_key,purpose) do update set relevance_note=excluded.relevance_note,verified_on=excluded.verified_on,metadata=excluded.metadata;

do $$ declare n integer; links integer; constr integer; bad integer; begin
 select count(*) into n from public.learning_unit_versions luv join public.learning_units lu on lu.id=luv.learning_unit_id where luv.content->>'didactic_version'='dl-rspp-authored-v3' and luv.status='draft' and (lu.stable_key like 'dl-rspp:%' or lu.stable_key like 'agg-dl-rspp:%' or lu.stable_key like 'dl-rspp-sector:agricoltura_zootecnia:%' or lu.stable_key like 'dl-rspp-sector:pesca:%' or lu.stable_key like 'dl-rspp-sector:chimico_petrolchimico:%'); if n<>53 then raise exception 'expected 53 authored drafts, got %',n; end if;
 select count(*) into links from public.course_module_units cmu join public.learning_unit_versions luv on luv.id=cmu.unit_version_id where luv.content->>'didactic_version'='dl-rspp-authored-v3'; if links<>0 then raise exception 'authored drafts unexpectedly linked: %',links; end if;
 select count(*) into constr from public.learning_unit_versions luv join public.learning_units lu on lu.id=luv.learning_unit_id where luv.content->>'didactic_version'='dl-rspp-authored-v3' and lu.stable_key like 'dl-rspp-sector:costruzioni:%'; if constr<>0 then raise exception 'construction units touched: %',constr; end if;
 select count(*) into bad from public.learning_unit_versions luv join public.learning_units lu on lu.id=luv.learning_unit_id where luv.content->>'didactic_version'='dl-rspp-authored-v3' and (luv.content->'quality'->>'teacher_ready' is distinct from 'true' or luv.content->'quality'->>'question_has_explanation' is distinct from 'true' or luv.content->'quality'->>'test_builder_excluded' is distinct from 'true' or luv.content->>'final_assessment' is distinct from 'false'); if bad<>0 then raise exception 'quality assertions failed for % units',bad; end if;
end $$;
